using System;using System.Windows;using System.Windows.Controls;
partial class TerminalWindow {
 void LocateTimeline(FrameworkElement chart,DateTime start,DateTime end){if(chart==null||end<=start)return;DependencyObject node=chart;while((node=System.Windows.Media.VisualTreeHelper.GetParent(node))!=null){var viewer=node as ScrollViewer;if(viewer==null)continue;viewer.UpdateLayout();double fraction=Math.Max(0,Math.Min(1,(DateTime.Now-start).TotalSeconds/(end-start).TotalSeconds));viewer.ScrollToHorizontalOffset(fraction*chart.ActualWidth-viewer.ViewportWidth/2);return;}}
 void AddTimelineZoom(Panel body,FrameworkElement chart,ScrollViewer viewer,string label){
  var row=new WrapPanel{Margin=new Thickness(0,4,0,4)};body.Children.Add(row);row.Children.Add(Text("时间轴缩放 · 图内滚轮",12));var slider=new Slider{Minimum=1,Maximum=6,Value=1,Width=145,TickFrequency=.25,IsSnapToTickEnabled=true,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(4,0,8,0)};System.Windows.Automation.AutomationProperties.SetName(slider,label+"缩放");var value=Text("1.0×",12);Action resize=()=>{double width=Math.Max(chart.MinWidth,viewer.ViewportWidth>0?viewer.ViewportWidth:650);double center=viewer.ExtentWidth>0?(viewer.HorizontalOffset+viewer.ViewportWidth/2)/viewer.ExtentWidth:0;chart.Width=width*slider.Value;chart.HorizontalAlignment=HorizontalAlignment.Left;viewer.UpdateLayout();if(center>0)viewer.ScrollToHorizontalOffset(Math.Max(0,center*viewer.ExtentWidth-viewer.ViewportWidth/2));value.Text=slider.Value.ToString("0.0")+"×";};Button(row,"－",()=>slider.Value=Math.Max(slider.Minimum,slider.Value-.5));row.Children.Add(slider);Button(row,"＋",()=>slider.Value=Math.Min(slider.Maximum,slider.Value+.5));row.Children.Add(value);Button(row,"重置缩放",()=>slider.Value=1);System.Windows.Controls.ToolTipService.SetIsEnabled(chart,false);viewer.AddHandler(System.Windows.Input.Mouse.PreviewMouseWheelEvent,new System.Windows.Input.MouseWheelEventHandler((s,e)=>{var origin=e.OriginalSource as DependencyObject;if(origin==null||origin!=chart&&!chart.IsAncestorOf(origin))return;double oldWidth=chart.ActualWidth;if(oldWidth<=0)return;double mouseInChart=e.GetPosition(chart).X;double mouseInViewport=e.GetPosition(viewer).X;double next=Math.Max(slider.Minimum,Math.Min(slider.Maximum,slider.Value+(e.Delta>0?.25:-.25)));if(next!=slider.Value){slider.Value=next;viewer.UpdateLayout();viewer.ScrollToHorizontalOffset(mouseInChart*chart.ActualWidth/oldWidth-mouseInViewport);}e.Handled=true;}),true);slider.ValueChanged+=(s,e)=>resize();viewer.SizeChanged+=(s,e)=>resize();viewer.Loaded+=(s,e)=>resize();
 }
}
